+    if (!tryToGroup(q->sourceModel()->index(sourceRow, 0))) {
+        q->beginInsertRows(QModelIndex(), rowMap.count(), rowMap.count());
+        rowMap.append(new QList<int>{sourceRow});
+        q->endInsertRows();
+    }
+}
