+void TaskGroupingProxyModel::requestAddToGroup(const QModelIndex &index, const QModelIndex &target)
+{
+    if (d->groupMode != TasksModel::GroupManual || !index.isValid() || index.model() != this || !target.isValid() || target.model() != this) {
+        return;
+    }
+
+    const QModelIndex groupIndex = target.parent().isValid() ? target.parent() : target;
+
+    if (index == groupIndex || index.parent() == groupIndex) {
+        return;
+    }
+
+    if (!index.data(AbstractTasksModel::IsWindow).toBool() || !groupIndex.data(AbstractTasksModel::IsWindow).toBool()) {
+        return;
+    }
+
+    const QList<int> groupRows = *d->rowMap.at(groupIndex.row());
+    const QList<int> movingRows = index.parent().isValid() ? QList<int>{mapToSource(index).row()} : *d->rowMap.at(index.row());
+
+    int group = d->manualGroups.value(d->manualGroupKey(sourceModel()->index(groupRows.constFirst(), 0)), -1);
+
+    if (group == -1) {
+        group = d->nextManualGroup++;
+    }
+
+    for (int row : groupRows) {
+        d->manualGroups.insert(d->manualGroupKey(sourceModel()->index(row, 0)), group);
+    }
+
+    for (int row : movingRows) {
+        d->manualGroups.insert(d->manualGroupKey(sourceModel()->index(row, 0)), group);
+        d->removeSourceRow(row);
+        d->insertSourceRow(row);
+    }
+}
+
+void TaskGroupingProxyModel::requestRemoveFromGroup(const QModelIndex &index)
+{
+    if (d->groupMode != TasksModel::GroupManual || !index.isValid() || index.model() != this) {
+        return;
+    }
+
+    if (!index.parent().isValid()) {
+        if (!d->isGroup(index.row())) {
+            return;
+        }
+
+        for (int row : *d->rowMap.at(index.row())) {
+            d->manualGroups.remove(d->manualGroupKey(sourceModel()->index(row, 0)));
+        }
+
+        d->breakGroupFor(index);
+
+        return;
+    }
+
+    const QList<int> members = *d->rowMap.at(index.parent().row());
+
+    if (members.count() == 2) {
+        requestRemoveFromGroup(index.parent());
+
+        return;
+    }
+
+    const int row = mapToSource(index).row();
+
+    d->manualGroups.remove(d->manualGroupKey(sourceModel()->index(row, 0)));
+    d->removeSourceRow(row);
+    d->insertSourceRow(row);
+}
 }

